#[Route('/api/token/refresh', methods: ['POST'])]
public function refresh(
    Request $request,
    RefreshTokenStore $store,
    AccessTokenIssuer $issuer,
): JsonResponse {
    $hash = hash('sha256', (string) $request->cookies->get('refresh_token'));
    $row = $store->findByHash($hash);
    if (null === $row || $row->isExpired()) {
        throw new AccessDeniedHttpException('Log in again.');
    }
    if ($row->isUsed()) {
        // a spent token came back: someone copied it
        $store->revokeAllFor($row->getUser());
        throw new AccessDeniedHttpException('Log in again.');
    }
    $store->markUsed($row);
    $newRefresh = $store->issueFor($row->getUser()); // random_bytes(32), saved hashed

    // $newRefresh travels back in an HttpOnly cookie (see the cookie slide)
    return new JsonResponse([
        'accessToken' => $issuer->create($row->getUser(), ttl: 900), // 15 minutes
    ]);
}

