#[Route('/auth/start', name: 'oidc_start')]
public function start(Request $request): RedirectResponse
{
    $verifier = rtrim(strtr(base64_encode(random_bytes(32)), '+/', '-_'), '=');
    $challenge = rtrim(strtr(base64_encode(hash('sha256', $verifier, true)), '+/', '-_'), '=');
    $session = $request->getSession();
    $session->set('pkce_verifier', $verifier);
    $session->set('oidc_state', $state = bin2hex(random_bytes(16)));
    $session->set('oidc_nonce', $nonce = bin2hex(random_bytes(16)));

    return new RedirectResponse('https://accounts.google.com/o/oauth2/v2/auth?'
        .http_build_query([
            'response_type' => 'code',
            'client_id' => $this->clientId,
            'redirect_uri' => $this->urls->generate('oidc_callback', [],
                UrlGeneratorInterface::ABSOLUTE_URL),
            'scope' => 'openid email profile',
            'state' => $state, 'nonce' => $nonce,
            'code_challenge' => $challenge, 'code_challenge_method' => 'S256',
        ]));
}

#[Route('/auth/callback', name: 'oidc_callback')]
public function callback(Request $request, HttpClientInterface $http): Response
{
    $s = $request->getSession();
    if (!hash_equals((string) $s->remove('oidc_state'), $request->query->getString('state'))) {
        throw new AccessDeniedHttpException('state mismatch');
    }
    $tokens = $http->request('POST', 'https://oauth2.googleapis.com/token', ['body' => [
        'grant_type' => 'authorization_code',
        'code' => $request->query->getString('code'),
        'redirect_uri' => $this->urls->generate('oidc_callback', [], 0),
        'client_id' => $this->clientId, 'client_secret' => $this->clientSecret,
        'code_verifier' => $s->remove('pkce_verifier'),
    ]])->toArray();

    [, $payload] = explode('.', $tokens['id_token']);
    $c = json_decode(base64_decode(strtr($payload, '-_', '+/')), true, 8, JSON_THROW_ON_ERROR);
    $nonce = (string) $s->remove('oidc_nonce');
    if ($c['iss'] !== 'https://accounts.google.com' || $c['aud'] !== $this->clientId
        || $c['exp'] < time() || !hash_equals($nonce, $c['nonce'] ?? '')) {
        throw new AccessDeniedHttpException('invalid id_token');
    }

    return $this->loginOrRegister($c['sub'], $c['email']);   // sub is the stable identity
}

final class ExpenseVoter extends Voter
{
    public const APPROVE = 'EXPENSE_APPROVE';

    public function __construct(private readonly Security $security) {}

    protected function supports(string $attribute, mixed $subject): bool
    {
        return self::APPROVE === $attribute && $subject instanceof Expense;
    }

    protected function voteOnAttribute(
        string $attribute, mixed $subject, TokenInterface $token, ?Vote $vote = null,
    ): bool {
        $user = $token->getUser();
        if (!$user instanceof User || !$this->security->isGranted('ROLE_MANAGER')) {
            return false;
        }

        $limit = $this->security->isGranted('ROLE_DIRECTOR') ? PHP_INT_MAX : 500;

        return $subject->getDepartment() === $user->getDepartment()  // own department
            && $subject->getAmountDollars() <= $limit                     // under the limit
            && $subject->getRequester() !== $user                      // not their own
            && $subject->isPending();
    }
}

