protected function voteOnAttribute(
    string $attribute, mixed $subject, TokenInterface $token, ?Vote $vote = null,
): bool {
    $user = $token->getUser();
    if (!$user instanceof User) {
        return false;
    }

    $relation = $this->relationOf($user, $subject->getFolder());

    return match ($attribute) {
        self::VIEW => null !== $relation,
        self::EDIT => \in_array($relation, ['editor', 'owner'], true),
        default => false,
    };
}

private function relationOf(User $user, ?Folder $folder): ?string
{
    for ($node = $folder; null !== $node; $node = $node->getParent()) {
        $grant = $this->grants->findOneBy(['folder' => $node, 'user' => $user]);
        if (null !== $grant) {
            return $grant->getRelation();   // 'viewer' | 'editor' | 'owner'
        }
    }

    return null;
}

