final class TenantFilter extends SQLFilter
{
    public function addFilterConstraint(
        ClassMetadata $targetEntity,
        string $targetTableAlias,
    ): string {
        // applies only to tenant-aware entities
        if (!$targetEntity->getReflectionClass()->implementsInterface(TenantAware::class)) {
            return '';
        }

        $tenant = $this->getParameter('tenant_id');   // quoted for us

        return sprintf('%s.tenant_id = %s', $targetTableAlias, $tenant);
    }
}

#[AsEventListener(event: KernelEvents::REQUEST, priority: 4)]   // after the firewall (8)
final class TenantFilterListener
{
    public function __construct(
        private readonly Security $security,
        private readonly EntityManagerInterface $em,
    ) {}

    public function __invoke(RequestEvent $event): void
    {
        $user = $this->security->getUser();
        if (!$event->isMainRequest() || !$user instanceof User) {
            return;
        }

        $filter = $this->em->getFilters()->enable('tenant');
        $filter->setParameter('tenant_id', (string) $user->getTenant()->getId());
    }
}

interface TenantAware
{
