    public function setTenant(Tenant $tenant): void;
}

#[AsDoctrineListener(event: Events::prePersist)]
final class TenantStampListener
{
    public function __construct(private readonly Security $security) {}

    public function prePersist(PrePersistEventArgs $args): void
    {
        $entity = $args->getObject();
        $user = $this->security->getUser();

        if ($entity instanceof TenantAware && $user instanceof User
            && null === $entity->getTenant()) {
            $entity->setTenant($user->getTenant());   // the user's, never the client's
        }
    }
}

#[AsEventListener(event: KernelEvents::REQUEST, priority: 3)]
final class TenantRateLimitListener
{
    public function __construct(
        private readonly Security $security,
        private readonly RateLimiterFactory $tenantApiLimiter,
    ) {}

    public function __invoke(RequestEvent $event): void
    {
        $user = $this->security->getUser();
        if (!$event->isMainRequest() || !$user instanceof User) {
            return;
        }

        // key = tenant, so one customer's rush can't empty another's bucket
        $key = (string) $user->getTenant()->getId();
        $limit = $this->tenantApiLimiter->create($key)->consume();
        if (!$limit->isAccepted()) {
            $wait = $limit->getRetryAfter()->getTimestamp() - time();
            throw new TooManyRequestsHttpException($wait);
        }
    }
}

