#[Route('/api/password/forgot', methods: ['POST'])]
public function forgot(
    #[MapRequestPayload] ForgotPassword $dto,
    Request $request,
    RateLimiterFactory $passwordResetLimiter,
    RateLimiterFactory $passwordResetEmailLimiter,
    MessageBusInterface $bus,
): JsonResponse {
    $email = mb_strtolower($dto->email);
    if (!$passwordResetLimiter->create($request->getClientIp())->consume()->isAccepted()
        || !$passwordResetEmailLimiter->create($email)->consume()->isAccepted()) {
        throw new TooManyRequestsHttpException();
    }

    // we don't check whether the email exists here; the handler will, in the background
    $bus->dispatch(new SendPasswordReset($email));

    return $this->json(['message' => 'If the email exists, a link has been sent.'], 202);
}

#[AsMessageHandler]
public function __invoke(SendPasswordReset $message): void
{
    $user = $this->users->findOneBy(['email' => $message->email]);
    if (null === $user) {
        return;                                        // stop quietly
    }

    $plain = bin2hex(random_bytes(32));                // 256 bits of randomness
    $this->em->persist(new ResetToken(
        $user, hash('sha256', $plain), new \DateTimeImmutable('+30 minutes'),
    ));
    $this->em->flush();

    $link = $this->urls->generate('password_reset', ['token' => $plain],
        UrlGeneratorInterface::ABSOLUTE_URL);          // host comes from config
    $this->mailer->send((new TemplatedEmail())->to($user->getEmail())
        ->subject('Password reset')->htmlTemplate('mail/reset.html.twig')
        ->context(['link' => $link]));
}

#[Route('/api/password/reset', methods: ['POST'])]
public function reset(
    #[MapRequestPayload] ResetPassword $dto,
    ResetTokenRepository $tokens,
    UserPasswordHasherInterface $hasher,
    RefreshTokenRepository $refresh,
    MessageBusInterface $bus,
    EntityManagerInterface $em,
): JsonResponse {
    $row = $tokens->claim(hash('sha256', $dto->token), new \DateTimeImmutable());
    if (null === $row) {
        return $this->json(['error' => 'The link is invalid or has expired'], 400);
    }

    $user = $row->getUser();
    $user->setPassword($hasher->hashPassword($user, $dto->newPassword));
    $refresh->revokeAllFor($user);    // revoke the old API tokens
    $em->flush();
    $bus->dispatch(new PasswordChanged($user->getId()));   // the warning email

    return $this->json(['message' => 'Your password has been changed.']);
}

