#[Route('/orders/{id}/refund', methods: ['POST'])]
#[IsGranted('REFUND', subject: 'order')]   // E, I: the voter looks at the object
public function refund(
    Order $order,
    RefundService $refunds,
    RateLimiterFactory $refundLimiter,
    #[CurrentUser] User $user,
): JsonResponse {
    // D: at most 3 refund attempts an hour per user
    $limit = $refundLimiter->create((string) $user->getId())->consume();
    if (!$limit->isAccepted()) {
        $retry = $limit->getRetryAfter()->getTimestamp() - time();
        throw new TooManyRequestsHttpException($retry);
    }

    // T: the amount comes from the order; a second refund of the same order is refused
    $refund = $refunds->refundFully($order, requestedBy: $user);

    // R: who, when, how much - the audit log
    $this->auditLogger->info('refund.issued', [
        'order_id' => $order->getId(),
        'actor_id' => $user->getId(),
        'amount_minor' => $refund->getAmountMinor(),
    ]);

    return $this->json(['refund_id' => $refund->getId()], 201);
}

