final class AvatarImporter
{
    private const ALLOWED_HOSTS = ['images.example.com', 'cdn.example.com'];
    private HttpClientInterface $client;

    public function __construct(HttpClientInterface $client)
    {
        // blocks requests to private/loopback/link-local IPs
        $this->client = new NoPrivateNetworkHttpClient($client);
    }

    public function fetch(string $url): string
    {
        $p = parse_url($url);
        if (($p['scheme'] ?? '') !== 'https'
            || !in_array($p['host'] ?? '', self::ALLOWED_HOSTS, true)) {
            throw new \InvalidArgumentException('Host is not allowed');
        }

        return $this->client->request('GET', $url, [
            'max_redirects' => 0,
            'timeout' => 3,
        ])->getContent();
    }
}

