final class FieldEncryptor
{
    public function __construct(
        #[Autowire(env: 'base64:FIELD_ENCRYPTION_KEY')]
        private readonly string $key, // a 32-byte key
    ) {
    }

    public function encrypt(string $plain): string
    {
        $nonce = random_bytes(SODIUM_CRYPTO_SECRETBOX_NONCEBYTES);

        return base64_encode($nonce.sodium_crypto_secretbox($plain, $nonce, $this->key));
    }

    public function decrypt(string $stored): string
    {
        $raw = base64_decode($stored, true);
        $n = SODIUM_CRYPTO_SECRETBOX_NONCEBYTES;
        $plain = sodium_crypto_secretbox_open(
            substr($raw, $n), substr($raw, 0, $n), $this->key
        );

        if (false === $plain) {
            throw new \RuntimeException('Could not decrypt');
        }

        return $plain;
    }
}

public function encrypt(string $plain): EncryptedBlob
{
    $result = $this->kms->generateDataKey([
        'KeyId' => $this->keyId,
        'KeySpec' => 'AES_256',
    ]);
    $dek = $result['Plaintext'];

    $nonce = random_bytes(SODIUM_CRYPTO_SECRETBOX_NONCEBYTES);
    $cipher = $nonce.sodium_crypto_secretbox($plain, $nonce, $dek);
    sodium_memzero($dek);

    return new EncryptedBlob($cipher, $result['CiphertextBlob']);
}

final readonly class EncryptedBlob
{
    public function __construct(public string $cipher, public string $lockedKey) {}
}

public function decrypt(EncryptedBlob $blob): string
{
    $result = $this->kms->decrypt(['CiphertextBlob' => $blob->lockedKey]);
    $dek = $result['Plaintext'];

    $n = SODIUM_CRYPTO_SECRETBOX_NONCEBYTES;
    $plain = sodium_crypto_secretbox_open(
        substr($blob->cipher, $n), substr($blob->cipher, 0, $n), $dek
    );
    sodium_memzero($dek);

    if (false === $plain) {
        throw new \RuntimeException('Could not decrypt');
    }

    return $plain;
}

