{
    $request = $event->getRequest();

    $this->logger->warning('Login failed', [
        'ip' => $request->getClientIp(),
        'reason' => $event->getException()::class,   // e.g. BadCredentialsException
        'request_id' => $request->headers->get('X-Request-Id'),
    ]);
}

#[AsMonologProcessor]
final class RedactSensitive implements ProcessorInterface
{
    private const KEYS = ['password', 'token', 'authorization', 'card_number', 'ssn'];

    public function __invoke(LogRecord $record): LogRecord
    {
        return $record->with(context: $this->redact($record->context));
    }

    private function redact(array $data): array
    {
        foreach ($data as $key => $value) {
            if (is_array($value)) {
                $data[$key] = $this->redact($value);
            } elseif (in_array(strtolower((string) $key), self::KEYS, true)) {
                $data[$key] = '[REDACTED]';
            }
        }

        return $data;
    }
}

