// Either the orders' foreign key blocks it, or a cascade wipes the money records
// the law says you must keep. The audit log doesn't say who asked either.

public function erase(User $user, User $requestedBy): void
{
    // Money transactions stay in the ledger (legal duty), but the person is erased
    $user->anonymize();
    $this->em->flush();

    $this->auditLogger->info('user.erased', [
        'user_id' => $user->getId(),
        'requested_by' => $requestedBy->getId(),
    ]);
}

// Inside the User entity
public function anonymize(): void
{
    $this->email = sprintf('deleted-%d@invalid.example', $this->id);
    $this->name = 'Deleted user';
    $this->phone = null;
    $this->erasedAt = new \DateTimeImmutable();
}
